/**
 * The countries whose flag Profile draws. Each one has a vector on every platform (generated by
 * scripts/generate-profile-flags.mjs: public/flags/<cc>.svg, an iOS Flags imageset, an Android flag_<cc> drawable).
 * Any other country falls back to its two-letter code in a chip, never to the flag emoji (Windows draws those as two
 * loose letters). src/lib/drawn-flags.test.ts keeps this list, the generator and the three platforms in step.
 */
export const DRAWN_FLAGS = [
  "AR",
  "AT",
  "BE",
  "BG",
  "CO",
  "DE",
  "EE",
  "ES",
  "FR",
  "GB",
  "HU",
  "ID",
  "IE",
  "IT",
  "LT",
  "LU",
  "MC",
  "NL",
  "PE",
  "PL",
  "RO",
  "RU",
  "UA",
  "US",
] as const;

export function drawnFlagCode(country: string | null | undefined): string | null {
  const code = country?.toUpperCase() ?? "";
  return (DRAWN_FLAGS as readonly string[]).includes(code) ? code : null;
}
